/**
 * markdownRenderer.js
 * Turns raw Markdown text into sanitized, styled HTML.
 *
 * Pipeline:
 *   1. marked.js parses Markdown -> HTML (GFM tables, lists, code, quotes,
 *      links, images, hr are all supported out of the box).
 *   2. DOMPurify sanitizes the HTML (defense in depth, since content is
 *      generated by our own Python script but this keeps things safe if
 *      the pipeline is reused for other sources later).
 *   3. Tables get wrapped in a scroll container for mobile.
 *   4. KaTeX auto-render turns $...$ / $$...$$ into rendered formulas.
 *
 * Keyword highlighting is applied separately, by keywordHighlighter.js,
 * AFTER this render step (it needs the final DOM).
 */

let configured = false;

function configureMarked() {
  if (configured) return;
  marked.setOptions({
    gfm: true, // GitHub-flavored markdown: tables, strikethrough, task lists
    breaks: false,
    headerIds: true,
    mangle: false,
  });
  configured = true;
}

/**
 * Render Markdown to a sanitized HTML string.
 * @param {string} markdownText
 * @returns {string} sanitized HTML
 */
export function renderMarkdownToHtml(markdownText) {
  configureMarked();
  const rawHtml = marked.parse(markdownText || "");
  const clean = DOMPurify.sanitize(rawHtml, {
    ADD_ATTR: ["target", "loading"],
  });
  return clean;
}

/** Wrap every <table> in a .table-scroll div so wide tables scroll on mobile. */
export function wrapTablesForScroll(container) {
  container.querySelectorAll("table").forEach((table) => {
    if (table.parentElement.classList.contains("table-scroll")) return;
    const wrapper = document.createElement("div");
    wrapper.className = "table-scroll";
    table.parentNode.insertBefore(wrapper, table);
    wrapper.appendChild(table);
  });
}

/** Make every image lazy-loaded (in case a Markdown image lacks it). */
export function lazyLoadImages(container) {
  container.querySelectorAll("img").forEach((img) => {
    if (!img.hasAttribute("loading")) img.setAttribute("loading", "lazy");
  });
}

/** Open every external link (not our own keyword links) in a new tab safely. */
export function hardenExternalLinks(container) {
  container.querySelectorAll("a:not(.kw-link)").forEach((a) => {
    const href = a.getAttribute("href") || "";
    if (/^https?:\/\//i.test(href)) {
      a.setAttribute("target", "_blank");
      a.setAttribute("rel", "noopener noreferrer");
    }
  });
}

/** Render KaTeX formulas ($...$ inline, $$...$$ display) found in the container. */
export function renderFormulas(container) {
  if (typeof renderMathInElement !== "function") return; // KaTeX auto-render not loaded
  renderMathInElement(container, {
    delimiters: [
      { left: "$$", right: "$$", display: true },
      { left: "$", right: "$", display: false },
      { left: "\\(", right: "\\)", display: false },
      { left: "\\[", right: "\\]", display: true },
    ],
    throwOnError: false,
  });
}
